<template><view class="page"><view class="profile row"><image src="/static/dengkemiao.png" mode="aspectFit"/><view class="identity"><view class="title">登科喵同学</view><view class="muted">坚持就是胜利</view></view><text class="badge">{{localMode?'本地体验':'备考同学'}}</text></view><view class="card stats"><view><view class="number">{{count}}</view><text>我的备考计划</text></view><view><view class="number">{{streak}}</view><text>连续打卡</text></view><view><view class="number">{{completed}}</view><text>完成任务</text></view></view><view v-if="error" class="error">{{error}}</view><view class="card menus"><view class="menu" @click="plan"><text><text class="menu-icon">▤</text>我的计划</text><text class="muted">›</text></view><view class="menu" @click="go('/pages/record/index')"><text><text class="menu-icon">▥</text>学习记录</text><text class="muted">›</text></view><view class="menu" @click="go('/pages/exam/create')"><text><text class="menu-icon">＋</text>创建备考计划</text><text class="muted">›</text></view><view class="menu" @click="go('/pages/payment/index')"><text><text class="menu-icon">☆</text>完整备考方案</text><text class="link">了解方案 ›</text></view><view class="menu" @click="privacy"><text><text class="menu-icon">▣</text>隐私与数据说明</text><text class="muted">›</text></view><view class="menu" @click="about"><text><text class="menu-icon">ⓘ</text>关于我们</text><text class="muted">›</text></view></view><view v-if="localMode" class="notice">本地体验：计划保存在当前设备，清除缓存会删除数据。</view><view class="muted version">登科喵备考计划 · V1.0 开发预览</view></view></template>
<script setup>
import {ref} from 'vue';import {onShow} from '@dcloudio/uni-app';import {api,localMode,selected} from '../../api'
const count=ref(0),streak=ref(0),completed=ref(0),error=ref('')
onShow(async()=>{error.value='';try{const ps=await api.plans();count.value=ps.length;completed.value=ps.reduce((a,p)=>a+p.completedTasks,0);const p=ps.find(p=>p.id===selected())||ps[0];streak.value=p?(await api.records(p.id)).streak:0}catch(e){error.value=e.message}})
function plan(){uni.switchTab({url:'/pages/plan/index'})}function go(url){uni.navigateTo({url})}function privacy(){uni.showModal({title:'隐私与数据说明',content:localMode?'本地模式的计划、任务和打卡数据存储于当前设备，不上传服务器。清除微信缓存将删除这些数据。正式上线前将提供完整隐私政策。':'服务端模式保存登录标识、备考计划及打卡记录，用于同步你的学习进度。正式上线前将提供完整隐私政策及数据删除入口。',showCancel:false})}function about(){uni.showModal({title:'登科喵备考计划',content:'通过规则与考试模板安排阶段路线和每日学习任务。计划仅作学习安排参考，请以实际考试大纲和通知为准。',showCancel:false})}
</script>
<style scoped>.profile{background:linear-gradient(120deg,#DEF0FF,#EDF7FF);border-radius:24rpx;padding:24rpx 20rpx;margin-top:10rpx}.profile image{width:115rpx;height:115rpx;border-radius:50%}.identity{flex:1}.identity .title{font-size:31rpx}.identity .muted{font-size:22rpx;color:#496D92}.profile .badge{font-size:19rpx;padding:4rpx 12rpx;white-space:nowrap}.stats{display:flex;justify-content:space-around;text-align:center;margin-top:20rpx;padding:24rpx 12rpx}.stats text{font-size:21rpx;color:#8A9BB3}.number{font-size:38rpx;font-weight:800;color:#132B4D}.menus{padding:8rpx 24rpx}.menu{display:flex;justify-content:space-between;align-items:center;padding:25rpx 0;border-bottom:1rpx solid #EDF1F7;font-size:26rpx}.menu:last-child{border:0}.menu-icon{display:inline-block;width:44rpx;color:#244B7B;font-size:30rpx}.menu .link{font-size:23rpx}.version{text-align:center;margin-top:35rpx}</style>
